parameters.jsCode:
const catalog = {
  name: "Universal API Gateway",
  version: "2.0.0",
  description: "Enterprise API Gateway - connect any AI to 30+ marketing, CRM, and business APIs",
  base_url: "https://mmurawala.app.n8n.cloud/webhook",
  authentication: {
    type: "api_key",
    header: "X-API-KEY",
    description: "Include your API key in the X-API-KEY header"
  },
  endpoints: {
    discovery: {
      method: "GET",
      path: "/api-discovery",
      description: "This endpoint - returns available APIs and their capabilities"
    },
    execute: {
      method: "POST",
      path: "/api-gateway",
      description: "Execute an API call",
      body: {
        client: { type: "string", required: true, description: "Client identifier (e.g., 'claude', 'chatgpt', 'gemini')" },
        api: { type: "string", required: true, description: "API identifier from the catalog below" },
        action: { type: "string", required: true, description: "Action to perform" },
        params: { type: "object", required: false, description: "Action-specific parameters" }
      }
    },
    health: {
      method: "GET",
      path: "/health-check",
      description: "Check health status of all APIs"
    }
  },
  apis: {
    marketing_ads: {
      google_ads: {
        description: "Google Ads campaign management",
        actions: {
          campaigns: { description: "List campaigns", params: { date_range: "LAST_7_DAYS|LAST_30_DAYS|ALL_TIME", limit: "number" } },
          ad_groups: { description: "List ad groups", params: { campaign_id: "string" } },
          ads: { description: "List ads", params: { ad_group_id: "string" } },
          keywords: { description: "List keywords", params: { ad_group_id: "string" } },
          metrics: { description: "Get performance metrics", params: { date_range: "string", metrics: "clicks,impressions,cost,conversions" } },
          create_campaign: { description: "Create a new campaign", params: { name: "string", budget: "number", type: "SEARCH|DISPLAY|VIDEO" } }
        }
      },
      meta_ads: {
        description: "Meta/Facebook Ads management",
        actions: {
          campaigns: { description: "List campaigns", params: { date_range: "string" } },
          ad_sets: { description: "List ad sets", params: { campaign_id: "string" } },
          ads: { description: "List ads", params: { ad_set_id: "string" } },
          insights: { description: "Get performance insights", params: { date_range: "string", breakdowns: "age,gender,placement" } },
          create_campaign: { description: "Create campaign", params: { name: "string", objective: "string", budget: "number" } }
        }
      },
      linkedin_ads: {
        description: "LinkedIn Ads management",
        actions: {
          campaigns: { description: "List campaigns", params: {} },
          analytics: { description: "Get analytics", params: { date_range: "string" } },
          create_campaign: { description: "Create campaign", params: { name: "string", objective: "string" } }
        }
      },
      tiktok_ads: {
        description: "TikTok Ads management",
        actions: {
          campaigns: { description: "List campaigns", params: {} },
          ad_groups: { description: "List ad groups", params: { campaign_id: "string" } },
          reports: { description: "Get reports", params: { date_range: "string" } }
        }
      }
    },
    crm: {
      hubspot: {
        description: "HubSpot CRM",
        actions: {
          contacts: { description: "List/search contacts", params: { query: "string", limit: "number" } },
          companies: { description: "List/search companies", params: { query: "string" } },
          deals: { description: "List/search deals", params: { stage: "string" } },
          create_contact: { description: "Create contact", params: { email: "string", firstname: "string", lastname: "string" } },
          create_deal: { description: "Create deal", params: { dealname: "string", amount: "number", stage: "string" } },
          pipelines: { description: "List pipelines", params: {} }
        }
      },
      salesforce: {
        description: "Salesforce CRM",
        actions: {
          accounts: { description: "List accounts", params: { query: "string" } },
          contacts: { description: "List contacts", params: { query: "string" } },
          opportunities: { description: "List opportunities", params: { stage: "string" } },
          leads: { description: "List leads", params: { status: "string" } },
          create_lead: { description: "Create lead", params: { company: "string", name: "string", email: "string" } },
          soql: { description: "Run SOQL query", params: { query: "string" } }
        }
      },
      pipedrive: {
        description: "Pipedrive CRM",
        actions: {
          deals: { description: "List deals", params: { status: "open|won|lost" } },
          persons: { description: "List persons", params: { query: "string" } },
          organizations: { description: "List organizations", params: {} },
          activities: { description: "List activities", params: { type: "string" } }
        }
      }
    },
    analytics: {
      ga4: {
        description: "Google Analytics 4",
        actions: {
          report: { description: "Run analytics report", params: { property_id: "string", date_range: "string", metrics: "sessions,users,pageviews", dimensions: "date,source,medium" } },
          realtime: { description: "Get realtime data", params: { property_id: "string" } },
          audiences: { description: "List audiences", params: { property_id: "string" } }
        }
      },
      search_console: {
        description: "Google Search Console",
        actions: {
          performance: { description: "Search performance report", params: { site_url: "string", date_range: "string", dimensions: "query,page,country" } },
          sitemaps: { description: "List sitemaps", params: { site_url: "string" } },
          inspect_url: { description: "Inspect URL", params: { url: "string", site_url: "string" } }
        }
      }
    },
    google_suite: {
      gmail: {
        description: "Gmail",
        actions: {
          list: { description: "List emails", params: { query: "string", max_results: "number" } },
          read: { description: "Read email", params: { message_id: "string" } },
          send: { description: "Send email", params: { to: "string", subject: "string", body: "string" } },
          search: { description: "Search emails", params: { query: "string" } }
        }
      },
      calendar: {
        description: "Google Calendar",
        actions: {
          events: { description: "List events", params: { calendar_id: "string", time_min: "ISO8601", time_max: "ISO8601" } },
          create_event: { description: "Create event", params: { summary: "string", start: "ISO8601", end: "ISO8601", attendees: "email[]" } },
          update_event: { description: "Update event", params: { event_id: "string", updates: "object" } }
        }
      },
      drive: {
        description: "Google Drive",
        actions: {
          list: { description: "List files", params: { query: "string", folder_id: "string" } },
          download: { description: "Download file", params: { file_id: "string" } },
          upload: { description: "Upload file", params: { name: "string", content: "string", folder_id: "string" } },
          search: { description: "Search files", params: { query: "string" } }
        }
      },
      sheets: {
        description: "Google Sheets",
        actions: {
          read: { description: "Read spreadsheet data", params: { spreadsheet_id: "string", range: "string" } },
          write: { description: "Write data", params: { spreadsheet_id: "string", range: "string", values: "array" } },
          append: { description: "Append rows", params: { spreadsheet_id: "string", range: "string", values: "array" } }
        }
      }
    }
  },
  usage_examples: [
    {
      description: "Get Google Ads campaigns for last 7 days",
      request: {
        method: "POST",
        url: "/api-gateway",
        headers: { "X-API-KEY": "your-key" },
        body: { client: "claude", api: "google_ads", action: "campaigns", params: { date_range: "LAST_7_DAYS" } }
      }
    },
    {
      description: "Search HubSpot contacts",
      request: {
        method: "POST",
        url: "/api-gateway",
        headers: { "X-API-KEY": "your-key" },
        body: { client: "claude", api: "hubspot", action: "contacts", params: { query: "john@example.com" } }
      }
    },
    {
      description: "Send an email via Gmail",
      request: {
        method: "POST",
        url: "/api-gateway",
        headers: { "X-API-KEY": "your-key" },
        body: { client: "claude", api: "gmail", action: "send", params: { to: "user@example.com", subject: "Hello", body: "Test email" } }
      }
    }
  ]
};

return [{ json: catalog }];
